#!/usr/bin/env bash
set -euo pipefail; source "$(dirname "$0")/deploy/lib.sh"
[[ $# == 1 ]] || die 'usage: restore-postgres.sh BACKUP'; backup="$1"; [[ -f "$backup" && ! -L "$backup" ]] || die 'unsafe backup'; [[ "${DX_REWORK_RESTORE_DRILL:-false}" == true && "${DX_REWORK_RESTORE_CONFIRM:-}" == RESTORE_TO_ISOLATED_DRILL ]] || die 'restore drill confirmation missing'
: "${DATABASE_URL:?source database required}"; : "${DX_REWORK_RESTORE_DATABASE_URL:?target database required}"; target="$DX_REWORK_RESTORE_DATABASE_URL"; name="$(node -e 'try{console.log(new URL(process.argv[1]).pathname.slice(1))}catch{process.exit(1)}' "$target")" || die 'cannot parse target URL'; [[ "$name" =~ (drill|restore|isolated|sandbox) ]] || die 'target lacks drill marker'; [[ ! "$name" =~ ^(postgres|template0|template1|dx_rework|production|prod)$ ]] || die 'production database name forbidden'
srcfp="$(printf %s "$DATABASE_URL"|sha256sum|cut -c1-12)"; dstfp="$(printf %s "$target"|sha256sum|cut -c1-12)"; [[ "$srcfp" != "$dstfp" ]] || die 'source and target fingerprint match'; meta="${backup%.dump}.metadata.json"; sum="${backup%.dump}.sha256"; [[ -f "$meta" && -f "$sum" ]] || die 'metadata/checksum missing'; (cd "$(dirname "$backup")" && sha256sum --check --strict "$(basename "$sum")") >/dev/null || die 'backup checksum damaged'; pg_restore --list "$backup" >/dev/null
count="$(psql "$target" -Atqc "select count(*) from pg_catalog.pg_tables where schemaname not in ('pg_catalog','information_schema')")"; [[ "$count" == 0 ]] || die 'target contains non-drill data'; start="$(date +%s)"; pg_restore --dbname="$target" --no-owner --no-acl --exit-on-error "$backup"; psql "$target" -v ON_ERROR_STOP=1 -Atqc "select 1; select count(*) from schema_migrations;" >/dev/null; end="$(date +%s)"; safe_log pass "restore drill source=$srcfp target=$dstfp rpo_seconds=unknown rto_seconds=$((end-start))"
